/* -------- module: core/04-highlight.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: highlight)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ============================================================
   Syntax Highlighter
   ============================================================ */

function highlight(code, lang) {
    var kw = LANG_KEYWORDS[lang] || [];
    var ty = LANG_TYPES[lang] || [];
    var bi = LANG_BUILTINS[lang] || [];
    var kwS = {}, tyS = {}, biS = {};
    kw.forEach(function (w) { kwS[w] = 1; });
    ty.forEach(function (w) { tyS[w] = 1; });
    bi.forEach(function (w) { biS[w] = 1; });

    var re = /(\/\/[^\n]*|\/\*[\s\S]*?\*\/|"(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|#[^\n]*|\b\d[\w.]*\b|[A-Za-z_]\w*)/g;
    var out = '';
    var last = 0;
    var m;
    while ((m = re.exec(code))) {
        if (m.index > last) out += escapeHtml(code.slice(last, m.index));
        var tok = m[0];
        var cls = null;
        if (tok.indexOf('//') === 0 || tok.indexOf('/*') === 0) cls = 'hl-comment';
        else if (tok.charAt(0) === '"' || tok.charAt(0) === "'") cls = 'hl-string';
        else if (tok.charAt(0) === '#') cls = 'hl-comment';
        else if (/^\d/.test(tok)) cls = 'hl-number';
        else if (/^[A-Za-z_]\w*$/.test(tok)) {
            if (kwS[tok]) cls = 'hl-keyword';
            else if (tyS[tok]) cls = 'hl-type';
            else if (biS[tok]) cls = 'hl-builtin';
            else if (/^\s*\(/.test(code.slice(re.lastIndex))) cls = 'hl-function';
        }
        out += cls ? '<span class="' + cls + '">' + escapeHtml(tok) + '</span>' : escapeHtml(tok);
        last = re.lastIndex;
    }
    out += escapeHtml(code.slice(last));
    return out;
}

/* -------- module: core/05-renderer.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: renderer)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ============================================================
   Markdown Renderer
   ============================================================ */

function escapeHtml(s) {
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function inline(text) {
    var html = escapeHtml(text);
    html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
    html = html.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
    html = html.replace(/\*([^*]+)\*/g, '<em>$1</em>');
    html = html.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, function (m, txt, href) {
        if (DB[href]) return '<a href="' + pageFile(href) + '">' + txt + '</a>';
        if (href.indexOf('coming-soon/') === 0) return '<a href="' + pageFile(href) + '">' + txt + '</a>';
        if (/^https?:/.test(href)) return '<a href="' + href + '" target="_blank" rel="noopener">' + txt + '</a>';
        if (href.charAt(0) === '#') return '<a href="' + href + '">' + txt + '</a>';
        return '<a href="' + pageFile(href) + '">' + txt + '</a>';
    });
    return html;
}

function isBlockStart(line) {
    if (!line.trim()) return true;
    if (/^~~~/.test(line)) return true;
    if (/^#{1,4}\s/.test(line)) return true;
    if (/^>/.test(line)) return true;
    if (/^\|.*\|$/.test(line.trim())) return true;
    if (/^(\s*)[-*+]\s+/.test(line)) return true;
    if (/^(\s*)(\d+)[.)]\s+/.test(line)) return true;
    if (/^(---+|\*\*\*+)$/.test(line.trim())) return true;
    return false;
}

function renderTable(headerLine, rows) {
    function cells(l) {
        return l.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map(function (c) { return c.trim(); });
    }
    var html = '<table><thead><tr>';
    cells(headerLine).forEach(function (c) { html += '<th>' + inline(c) + '</th>'; });
    html += '</tr></thead><tbody>';
    rows.forEach(function (r) {
        html += '<tr>';
        cells(r).forEach(function (c) { html += '<td>' + inline(c) + '</td>'; });
        html += '</tr>';
    });
    html += '</tbody></table>';
    return html;
}

function renderListLines(lines, ordered) {
    var tag = ordered ? 'ol' : 'ul';
    var items = [];
    lines.forEach(function (line) {
        var m = line.match(/^(\s*)(?:[-*+]|\d+[.)])\s+(.*)$/);
        items.push({ depth: m ? Math.floor(m[1].length / 2) : 0, text: m ? m[2] : '' });
    });
    var root = [];
    var stack = [{ children: root, depth: -1 }];
    items.forEach(function (it) {
        while (stack[stack.length - 1].depth >= it.depth) stack.pop();
        it.children = [];
        stack[stack.length - 1].children.push(it);
        stack.push(it);
    });
    function emit(list) {
        var h = '<' + tag + '>';
        list.forEach(function (it) {
            h += '<li>' + inline(it.text);
            if (it.children.length) h += emit(it.children);
            h += '</li>';
        });
        return h + '</' + tag + '>';
    }
    return emit(root);
}

function renderBlockquote(buf) {
    var first = buf[0].trim();
    var m = first.match(/^\[!(info|warning|success|danger)\](?:\s+(.*))?$/i);
    if (m) {
        var type = m[1].toLowerCase();
        var body = buf.slice(1);
        if (m[2]) body.unshift(m[2]);
        return '<div class="callout callout-' + type + '">' + body.map(inline).join(' ') + '</div>';
    }
    return '<blockquote>' + buf.map(inline).join(' ') + '</blockquote>';
}

function renderProblem(src) {
    var f = {};
    var cur = null;
    var keys = ['title', 'difficulty', 'source', 'tags', 'statement', 'approach', 'time', 'space', 'solution'];
    src.split('\n').forEach(function (line) {
        var m = line.match(/^([a-z_]+)\s*:\s?(.*)$/i);
        if (m && keys.indexOf(m[1].toLowerCase()) !== -1) {
            cur = m[1].toLowerCase();
            f[cur] = m[2].trim();
        } else if (cur) {
            f[cur] += '\n' + line;
        }
    });
    var diff = (f.difficulty || 'medium').toLowerCase();
    var badge = diff === 'easy' ? 'badge-easy' : diff === 'hard' ? 'badge-hard' : 'badge-medium';
    var html = '<div class="problem-card">';
    html += '<div class="problem-header">';
    html += '<h3 class="problem-title">' + escapeHtml(f.title || 'Problem') + '</h3>';
    html += '<span class="badge ' + badge + '">' + diff + '</span>';
    html += '</div>';
    html += '<div class="problem-meta">';
    if (f.source) html += '<span class="tag">' + escapeHtml(f.source) + '</span>';
    (f.tags || '').split(',').forEach(function (t) {
        t = t.trim();
        if (t) html += '<span class="tag">' + escapeHtml(t) + '</span>';
    });
    html += '</div>';
    if (f.statement) html += '<p class="problem-statement">' + inline(f.statement) + '</p>';
    if (f.approach) html += '<h4>Approach</h4><p>' + inline(f.approach) + '</p>';
    if (f.time || f.space) {
        html += '<div class="problem-meta">';
        if (f.time) html += '<span class="tag">Time: ' + escapeHtml(f.time) + '</span>';
        if (f.space) html += '<span class="tag">Space: ' + escapeHtml(f.space) + '</span>';
        html += '</div>';
    }
    if (f.solution) {
        html += '<button class="problem-solution-btn" data-group="' + escapeHtml(f.solution.trim()) + '">View code</button>';
    }
    html += '</div>';
    return html;
}

function renderCodeBlock(lang, code) {
    var label = (LANG_LABELS[lang] || lang || 'code').toUpperCase();
    var highlighted = highlight(code, lang);
    return '<div class="code-block" data-lang="' + lang + '">' +
        '<div class="code-header">' +
        '<span class="lang-label">' + label + '</span>' +
        '<select class="lang-switch" aria-label="Switch language">' + langSelectOptions(lang) + '</select>' +
        '<span class="code-actions">' +
        '<button class="code-action-btn" data-action="expand">Expand</button>' +
        '<button class="code-action-btn" data-action="copy">Copy</button>' +
        '</span>' +
        '</div>' +
        '<pre><code class="language-' + lang + '">' + highlighted + '</code></pre>' +
        '</div>';
}

function expandRefShorthand(text) {
    return String(text).replace(/\[([^\]]+)\]\(\{([a-z]+):([a-zA-Z0-9_]+)\}\)/gi, function (m, label, lang, token) {
        var u = refUrl(lang, token);
        return u ? '[' + label + '](' + u + ')' : '[' + label + '](#)';
    });
}

function renderIo(src) {
    var input = [];
    var output = [];
    var section = null;
    src.split('\n').forEach(function (line) {
        var m = line.match(/^(input|output)\s*:\s?(.*)$/i);
        if (m) {
            section = m[1].toLowerCase();
            if (m[2]) (section === 'input' ? input : output).push(m[2]);
            return;
        }
        if (section === 'input') input.push(line);
        else if (section === 'output') output.push(line);
    });
    var html = '<div class="io-box">';
    if (input.length) {
        html += '<div class="io-section io-input">' +
            '<div class="io-label">Sample Input</div>' +
            '<pre>' + escapeHtml(input.join('\n')) + '</pre></div>';
    }
    if (output.length) {
        html += '<div class="io-section io-output">' +
            '<div class="io-label">Sample Output (expected)</div>' +
            '<pre>' + escapeHtml(output.join('\n')) + '</pre></div>';
    }
    html += '</div>';
    return html;
}

function renderExplain(src) {    var meta = {};
    var code = [];
    var expl = [];
    var seenSeparator = false;
    src.split('\n').forEach(function (line) {
        var m = line.match(/^([a-z_]+)\s*:\s?(.*)$/i);
        if (!seenSeparator && m && ['lang', 'group', 'level', 'topic'].indexOf(m[1].toLowerCase()) !== -1) {
            meta[m[1].toLowerCase()] = m[2].trim();
            return;
        }
        if (!seenSeparator && /^---+\s*$/.test(line.trim())) { seenSeparator = true; return; }
        if (seenSeparator) {
            var em = line.match(/^##(\d+)##\s*(.*)$/);
            if (em) expl.push({ n: parseInt(em[1], 10), text: em[2] });
        } else {
            code.push(line);
        }
    });
    var lang = meta.lang || 'cpp';
    var group = meta.group || '';
    var html = '<div class="code-explain" data-lang="' + lang + '" data-group="' + group + '">';
    html += renderCodeBlock(lang, code.join('\n'));
    if (expl.length) {
        html += '<ol class="explain-lines">';
        expl.forEach(function (e) {
            html += '<li><span class="line-num">' + e.n + '</span><span class="explain-text">' +
                inline(expandRefShorthand(e.text)) + '</span></li>';
        });
        html += '</ol>';
    }
    html += '</div>';
    return html;
}

function renderMarkdown(md) {
    var lines = String(md || '').split('\n');
    var i = 0;
    var out = [];
    while (i < lines.length) {
        var line = lines[i];
        if (!line.trim()) { i++; continue; }

        var fence = line.match(/^~~~(\w*)\s*$/);
        if (fence) {
            var lang = fence[1];
            var buf = [];
            i++;
            while (i < lines.length && !/^~~~\s*$/.test(lines[i])) {
                buf.push(lines[i]); i++;
            }
            i++;
            out.push(lang === 'explain' ? renderExplain(buf.join('\n'))
                : lang === 'problem' ? renderProblem(buf.join('\n'))
                : lang === 'io' ? renderIo(buf.join('\n'))
                : renderCodeBlock(lang, buf.join('\n')));
            continue;
        }

        var h = line.match(/^(#{1,4})\s+(.*)$/);
        if (h) {
            out.push('<h' + h[1].length + '>' + inline(h[2]) + '</h' + h[1].length + '>');
            i++; continue;
        }

        if (/^(---+|\*\*\*+)$/.test(line.trim())) {
            out.push('<hr>'); i++; continue;
        }

        if (/^>\s*/.test(line)) {
            var q = [];
            while (i < lines.length && /^>\s*/.test(lines[i])) {
                q.push(lines[i].replace(/^>\s?/, ''));
                i++;
            }
            out.push(renderBlockquote(q));
            continue;
        }

        if (/^\|.*\|$/.test(line.trim()) && i + 1 < lines.length && /^\|[\s:\-|]+\|$/.test(lines[i + 1].trim())) {
            var header = line;
            var rows = [];
            i += 2;
            while (i < lines.length && /^\|.*\|$/.test(lines[i].trim())) {
                rows.push(lines[i]); i++;
            }
            out.push(renderTable(header, rows));
            continue;
        }

        var ul = line.match(/^(\s*)[-*+]\s+/);
        if (ul) {
            var lbuf = [line];
            i++;
            while (i < lines.length && /^(\s*)[-*+]\s+/.test(lines[i])) {
                lbuf.push(lines[i]); i++;
            }
            out.push(renderListLines(lbuf, false));
            continue;
        }

        var ol = line.match(/^(\s*)(\d+)[.)]\s+/);
        if (ol) {
            var obuf = [line];
            i++;
            while (i < lines.length && /^(\s*)(\d+)[.)]\s+/.test(lines[i])) {
                obuf.push(lines[i]); i++;
            }
            out.push(renderListLines(obuf, true));
            continue;
        }

        var pbuf = [line];
        i++;
        while (i < lines.length && lines[i].trim() && !isBlockStart(lines[i])) {
            pbuf.push(lines[i]); i++;
        }
        out.push('<p>' + inline(pbuf.join(' ')) + '</p>');
    }
    return out.join('\n');
}

/* -------- module: core/06-search.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: search)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ============================================================
   Search Index
   ============================================================ */

var SEARCH_INDEX = [];

function buildIndex() {
    SEARCH_INDEX = [];
    Object.keys(DB).forEach(function (id) {
        var d = DB[id];
        var text = (d.content || '').replace(/~~~\w*\s*/g, ' ').replace(/[`#*_>|[\]]/g, ' ').toLowerCase();
        SEARCH_INDEX.push({ id: id, title: d.title, crumbs: d.crumbs, text: text });
    });
}

function searchIndex(query) {
    var q = query.trim().toLowerCase();
    if (!q) return [];
    var terms = q.split(/\s+/);
    var res = [];
    SEARCH_INDEX.forEach(function (page) {
        var hay = page.title.toLowerCase() + ' ' + page.text;
        for (var t = 0; t < terms.length; t++) {
            if (hay.indexOf(terms[t]) === -1) return;
        }
        var score = 0;
        terms.forEach(function (term) {
            if (page.title.toLowerCase().indexOf(term) !== -1) score += 10;
            if (page.text.indexOf(term) !== -1) score += 1;
        });
        res.push({ page: page, score: score });
    });
    res.sort(function (a, b) { return b.score - a.score; });
    return res.slice(0, 20);
}

/* ============================================================
   Search Modal
   ============================================================ */

function openSearch() {
    $('#searchModal').classList.add('open');
    $('#modalSearchInput').value = '';
    selectedResult = -1;
    $('#searchResults').innerHTML = '<div class="search-empty"><p>Type to search across all topics, problems, and patterns.</p></div>';
    setTimeout(function () { $('#modalSearchInput').focus(); }, 50);
}

function closeSearch() {
    $('#searchModal').classList.remove('open');
}

function snippetFor(page, query) {
    var term = query.trim().toLowerCase().split(/\s+/)[0];
    var idx = page.text.indexOf(term);
    var start = Math.max(0, idx - 40);
    var raw = page.text.slice(start, start + 120);
    return (start > 0 ? '…' : '') + raw + '…';
}

function renderSearchResults(results, query) {
    var el = $('#searchResults');
    if (!results.length) {
        el.innerHTML = '<div class="search-empty"><p>No matches for "' + escapeHtml(query) + '".</p></div>';
        return;
    }
    el.innerHTML = '';
    results.forEach(function (r, i) {
        var item = document.createElement('div');
        item.className = 'search-result-item' + (i === 0 ? ' selected' : '');
        item.innerHTML =
            '<span class="search-result-title">' + escapeHtml(r.page.title) + '</span>' +
            '<span class="search-result-path">' + r.page.crumbs.map(escapeHtml).join(' / ') + '</span>' +
            '<span class="search-result-preview">' + escapeHtml(snippetFor(r.page, query)) + '</span>';
        item.addEventListener('click', function () {
            navigate(r.page.id);
            closeSearch();
        });
        el.appendChild(item);
        if (i === 0) selectedResult = 0;
    });
}

function selectResult(items, idx) {
    if (idx < 0 || idx >= items.length) return;
    items.forEach(function (it) { it.classList.remove('selected'); });
    items[idx].classList.add('selected');
    selectedResult = idx;
    items[idx].scrollIntoView({ block: 'nearest' });
}

/* -------- module: core/07-router.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: router)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ---------- Multi-page file mapping ----------
   Each DB path maps to its own static HTML file.
   home -> index.html | research/array -> array.html
   coming-soon/<id> -> <id>.html | topics/prefix-sum -> topics-prefix-sum.html
   ============================================================ */

var PAGE_FILE = {
    'home': 'index.html',
    'research/array': 'array.html'
};

function pageFile(path) {
    if (PAGE_FILE[path]) return PAGE_FILE[path];
    if (path.indexOf('coming-soon/') === 0) return path.replace('coming-soon/', '') + '.html';
    return path.replace(/\//g, '-') + '.html';
}

function parsePath() {
    return (document.body && document.body.getAttribute('data-path')) || 'home';
}

/* ---------- Hash-based SPA routing ----------
   Kept alongside the MPA build so a single file (index.html or the
   standalone bundle) can navigate entirely in-place via #/path.
   Works over http://, file:// and Android content://. */

function parseHashPath() {
    var m = window.location.hash.match(/^#\/([^?]*)/);
    return m ? decodeURIComponent(m[1]) : null;
}

function navigate(path) {
    var target = '#/' + path;
    if (target === window.location.hash) return;
    window.location.hash = target;
}

function bindHashRouter() {
    window.addEventListener('hashchange', function () {
        var p = parseHashPath();
        if (p) renderPath(p);
    });
}

function renderPath(path) {
    if (path === 'home') renderHome();
    else if (path.indexOf('coming-soon/') === 0) renderComingSoon(path.replace('coming-soon/', ''));
    else if (DB[path]) renderPage(path);
    else renderHome();
}

function setProgress(pct) {
    var el = $('#scrollProgress');
    if (el) el.style.width = pct + '%';
}

/* ---------- Dashboard Renderer ---------- */

function renderHome() {
    currentPath = 'home';
    document.title = 'DSA Knowledge Base — Dashboard';

    var activeCount = 0;
    var totalTopics = 0;
    var totalProblems = 0;
    DS_CARDS.forEach(function (c) {
        if (c.status === 'active') activeCount++;
        totalTopics += c.topics;
        totalProblems += c.problems;
    });

    var statsHtml =
        '<div class="stats-row">' +
            '<div class="stat-card reveal-on-scroll">' +
                '<div class="stat-number" data-target="' + DS_CARDS.length + '">0</div>' +
                '<div class="stat-label">Data Structures</div>' +
            '</div>' +
            '<div class="stat-card reveal-on-scroll">' +
                '<div class="stat-number" data-target="' + totalTopics + '">0</div>' +
                '<div class="stat-label">Topics</div>' +
            '</div>' +
            '<div class="stat-card reveal-on-scroll">' +
                '<div class="stat-number" data-target="' + totalProblems + '">0</div>' +
                '<div class="stat-label">Problems</div>' +
            '</div>' +
            '<div class="stat-card reveal-on-scroll">' +
                '<div class="stat-number" data-target="5">0</div>' +
                '<div class="stat-label">Languages</div>' +
            '</div>' +
        '</div>';

    var cardsHtml = '';
    DS_CARDS.forEach(function (c, i) {
        var isActive = c.status === 'active';
        var statusBadge = isActive
            ? '<span class="ds-badge ds-badge-active">Active</span>'
            : '<span class="ds-badge ds-badge-soon">Coming Soon</span>';
        var topicCount = isActive
            ? '<span class="ds-topic-count">' + c.topics + ' topics</span>'
            : '<span class="ds-topic-count">' + c.expectedTopics.length + ' planned</span>';
        var clickAttr = ' onclick="navigate(\'' + c.path + '\')"';

        cardsHtml +=
            '<div class="ds-card' + (isActive ? ' ds-card-active' : ' ds-card-soon') + '"' +
            ' style="--card-color:' + c.color + '; animation-delay:' + (0.05 + i * 0.05) + 's"' +
            clickAttr + '>' +
                '<div class="ds-card-icon" style="color:' + c.color + '">' + c.icon + '</div>' +
                '<div class="ds-card-body">' +
                    '<h3 class="ds-card-title">' + escapeHtml(c.title) + '</h3>' +
                    '<p class="ds-card-desc">' + escapeHtml(c.desc) + '</p>' +
                '</div>' +
                '<div class="ds-card-footer">' +
                    statusBadge +
                    topicCount +
                '</div>' +
            '</div>';
    });

    var html =
        '<div class="dashboard-hero">' +
            '<h1>DSA Knowledge Base</h1>' +
            '<p class="dashboard-subtitle">Master Data Structures &amp; Algorithms — research notes, topics, interview prep, LeetCode, Codeforces, and code snippets. Everything works offline.</p>' +
        '</div>' +
        statsHtml +
        '<div class="dashboard-section">' +
            '<div class="dashboard-section-header">' +
                '<h2>Data Structures</h2>' +
            '</div>' +
            '<div class="ds-card-grid">' + cardsHtml + '</div>' +
        '</div>';

    $('#article').innerHTML = html;
    safe(initLangPref);
    safe(initScrollReveal);
    safe(animateCounters);
    renderBreadcrumb(['Home']);
    updateNavActive('home');
    expandToCurrent();
    $('#content').scrollTop = 0;
    setProgress(0);
}

/* ---------- Coming Soon Renderer ---------- */

function renderComingSoon(dsId) {
    var card = null;
    DS_CARDS.forEach(function (c) { if (c.id === dsId) card = c; });
    if (!card) { renderHome(); return; }

    currentPath = 'coming-soon/' + dsId;
    document.title = card.title + ' — Coming Soon — DSA Knowledge Base';

    var topicsList = '';
    card.expectedTopics.forEach(function (t) {
        topicsList += '<li class="coming-soon-topic">' +
            '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/></svg>' +
            escapeHtml(t) +
            '</li>';
    });

    var html =
        '<div class="coming-soon-page">' +
            '<div class="coming-soon-icon" style="color:' + card.color + '">' +
                '<svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" class="coming-soon-lock">' +
                    '<rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>' +
                    '<path d="M7 11V7a5 5 0 0 1 10 0v4"/>' +
                '</svg>' +
            '</div>' +
            '<h1 class="coming-soon-title">' + escapeHtml(card.title) + '</h1>' +
            '<p class="coming-soon-desc">' + escapeHtml(card.desc) + '</p>' +
            '<div class="shimmer-bar"><div class="shimmer-fill" style="background:' + card.color + '"></div></div>' +
            '<div class="coming-soon-topics">' +
                '<h3>Expected Topics</h3>' +
                '<ul class="coming-soon-list">' + topicsList + '</ul>' +
            '</div>' +
            '<div class="coming-soon-cta">' +
                '<p>This section is under active development. Want to contribute?</p>' +
                '<a href="#/home" class="btn btn-primary" style="background:' + card.color + '; border-color:' + card.color + '">Back to Dashboard</a>' +
            '</div>' +
        '</div>';

    $('#article').innerHTML = html;
    safe(initScrollReveal);
    renderBreadcrumb(['Home', card.title]);
    updateNavActive('coming-soon/' + dsId);
    expandToCurrent();
    updateBookmarkBtn();
    $('#content').scrollTop = 0;
    setProgress(0);
}

/* ---------- Page Renderer (with transition) ---------- */

function renderPage(path) {
    var page = DB[path];
    if (!page) { renderHome(); return; }
    currentPath = path;
    document.title = page.title + ' — DSA Knowledge Base';
    $('#article').innerHTML = renderMarkdown(page.content);
    safe(initLangTabsAll);
    safe(initScrollReveal);
    renderBreadcrumb(page.crumbs || ['Home', page.title]);
    updateNavActive(path);
    expandToCurrent();
    updateBookmarkBtn();
    $('#content').scrollTop = 0;
    setProgress(0);
}

/* ---------- Breadcrumb & Nav ---------- */

function renderBreadcrumb(crumbs) {
    $('#breadcrumb').innerHTML = crumbs.map(function (c, i) {
        var last = i === crumbs.length - 1;
        return '<span class="breadcrumb-item' + (last ? ' breadcrumb-current' : '') + '">' +
            escapeHtml(c) + '</span>' + (last ? '' : '<span class="breadcrumb-separator">/</span>');
    }).join('');
}

function updateNavActive(path) {
    $$('.sidebar .nav-item[data-path]').forEach(function (el) {
        el.classList.toggle('active', el.getAttribute('data-path') === path);
    });
}

function expandToCurrent() {
    var active = $('.sidebar .nav-item.active[data-path]');
    if (!active) return;
    var el = active.parentElement;
    while (el && !el.classList.contains('sidebar')) {
        if (el.classList.contains('nav-children')) {
            el.classList.add('open');
            var prev = el.previousElementSibling;
            if (prev && prev.classList.contains('nav-parent')) prev.classList.add('expanded');
        }
        el = el.parentElement;
    }
}

/* ---------- Scroll Reveal ---------- */

function initScrollReveal() {
    var observer = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
            if (entry.isIntersecting) {
                entry.target.classList.add('revealed');
                observer.unobserve(entry.target);
            }
        });
    }, { threshold: 0.1 });

    $$('.reveal-on-scroll').forEach(function (el) {
        if (!el.classList.contains('revealed')) observer.observe(el);
    });
}

/* ---------- Animated Counters ---------- */

function animateCounters() {
    $$('.stat-number[data-target]').forEach(function (el) {
        var target = parseInt(el.getAttribute('data-target'), 10);
        var duration = 800;
        var start = performance.now();

        function step(now) {
            var elapsed = now - start;
            var progress = Math.min(elapsed / duration, 1);
            var eased = 1 - Math.pow(1 - progress, 3);
            el.textContent = Math.round(eased * target);
            if (progress < 1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
    });
}

/* -------- module: core/08-ui.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: ui)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ============================================================
   Bookmarks
   ============================================================ */

function getBookmarks() {
    try {
        return JSON.parse(storage.get('dsa_bookmarks') || '[]');
    } catch (e) {
        return [];
    }
}

function saveBookmarks(list) {
    storage.set('dsa_bookmarks', JSON.stringify(list));
}

function updateBookmarkBtn() {
    $('#bookmarkBtn').classList.toggle('active', getBookmarks().indexOf(currentPath) >= 0);
}

function renderBookmarks() {
    var list = getBookmarks();
    var el = $('#bookmarksList');
    if (!list.length) {
        el.innerHTML = '<p class="bookmarks-empty">No bookmarks yet. Press Ctrl+B on any page to bookmark it.</p>';
        return;
    }
    el.innerHTML = '';
    list.forEach(function (p) {
        var d = DB[p];
        if (!d) return;
        var item = document.createElement('div');
        item.className = 'bookmark-item';
        item.innerHTML = '<svg width="16" height="16" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"></path></svg><span>' + escapeHtml(d.title) + '</span>';
        item.addEventListener('click', function () {
            navigate(p);
            closeBookmarks();
        });
        el.appendChild(item);
    });
}

/* ============================================================
   Theme
   ============================================================ */

function initTheme() {
    var saved = storage.get('dsa_theme');
    document.documentElement.setAttribute('data-theme', saved === 'dark' ? 'dark' : 'light');
}

/* ============================================================
   Bookmarks Panel
   ============================================================ */

function openBookmarks() {
    renderBookmarks();
    $('#bookmarksPanel').classList.add('open');
}

function closeBookmarks() {
    $('#bookmarksPanel').classList.remove('open');
}

/* ============================================================
   Code Blocks
   ============================================================ */

function copyText(text, btn) {
    function done() {
        btn.textContent = 'Copied';
        btn.classList.add('copied');
        setTimeout(function () {
            btn.textContent = 'Copy';
            btn.classList.remove('copied');
        }, 1600);
    }
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, function () { fallbackCopy(text); done(); });
    } else {
        fallbackCopy(text);
        done();
    }
}

function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta);
}

function bindCodeBlocks() {
    $('#article').addEventListener('click', function (e) {
        var card = e.target.closest('.card[data-path]');
        if (card) {
            navigate(card.getAttribute('data-path'));
            return;
        }
        var btn = e.target.closest('.code-action-btn');
        if (!btn) return;
        var block = btn.closest('.code-block');
        var codeEl = block.querySelector('code');
        if (btn.getAttribute('data-action') === 'copy') {
            copyText(codeEl.textContent, btn);
        } else if (btn.getAttribute('data-action') === 'expand') {
            var expanded = codeEl.style.maxHeight === 'none';
            codeEl.style.maxHeight = expanded ? '' : 'none';
            btn.textContent = expanded ? 'Expand' : 'Collapse';
        }
    });
}

/* ============================================================
   Toast
   ============================================================ */

function toast(msg) {
    var el = $('#toast');
    if (!el) {
        el = document.createElement('div');
        el.id = 'toast';
        el.style.cssText = 'position:fixed;bottom:24px;left:50%;transform:translateX(-50%) translateY(16px);background:#24292f;color:#fff;padding:10px 18px;border-radius:8px;box-shadow:0 4px 16px rgba(0,0,0,.25);font-size:13px;z-index:300;opacity:0;transition:all .25s ease;font-family:inherit;';
        document.body.appendChild(el);
    }
    el.textContent = msg;
    requestAnimationFrame(function () {
        el.style.opacity = '1';
        el.style.transform = 'translateX(-50%) translateY(0)';
    });
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
        el.style.opacity = '0';
        el.style.transform = 'translateX(-50%) translateY(16px)';
    }, 1800);
}

/* ============================================================
   Scroll Progress & Back to Top
   ============================================================ */

function bindScroll() {
    var content = $('#content');
    content.addEventListener('scroll', function () {
        var max = content.scrollHeight - content.clientHeight;
        var pct = max > 0 ? (content.scrollTop / max) * 100 : 0;
        setProgress(pct);
    });
    $('#backToTop').addEventListener('click', function () {
        content.scrollTo({ top: 0, behavior: 'smooth' });
    });
}

/* ============================================================
   Sidebar & Navigation
   ============================================================ */

function bindSidebar() {
    $('#sidebarToggle').addEventListener('click', function () {
        $('#sidebar').classList.toggle('open');
    });

    $$('.sidebar .nav-item').forEach(function (el) {
        el.addEventListener('click', function (e) {
            e.preventDefault();
            if (el.classList.contains('nav-parent')) {
                el.classList.toggle('expanded');
                var next = el.nextElementSibling;
                if (next && next.classList.contains('nav-children')) next.classList.toggle('open');
                return;
            }
            var path = el.getAttribute('data-path');
            if (path) {
                navigate(path);
                $('#sidebar').classList.remove('open');
            }
        });
    });

    $('#copyPathBtn').addEventListener('click', function () {
        copyText(currentPath, this);
        toast('Path copied: ' + currentPath);
    });

    $('#bookmarkBtn').addEventListener('click', function () {
        var list = getBookmarks();
        var idx = list.indexOf(currentPath);
        if (idx >= 0) {
            list.splice(idx, 1);
            saveBookmarks(list);
            toast('Bookmark removed');
        } else {
            list.push(currentPath);
            saveBookmarks(list);
            toast('Bookmarked');
        }
        updateBookmarkBtn();
        renderBookmarks();
    });
}

/* ============================================================
   Search & Modal Bindings
   ============================================================ */

function bindSearch() {
    $('#searchInput').addEventListener('focus', function () { openSearch(); });
    $('#searchBackdrop').addEventListener('click', closeSearch);

    $('#modalSearchInput').addEventListener('input', function () {
        var q = this.value;
        renderSearchResults(searchIndex(q), q);
    });

    $('#modalSearchInput').addEventListener('keydown', function (e) {
        var items = $$('#searchResults .search-result-item');
        if (!items.length) return;
        var cur = selectedResult;
        if (e.key === 'ArrowDown') {
            e.preventDefault();
            selectResult(items, (cur + 1) % items.length);
        } else if (e.key === 'ArrowUp') {
            e.preventDefault();
            selectResult(items, cur <= 0 ? items.length - 1 : cur - 1);
        } else if (e.key === 'Enter') {
            e.preventDefault();
            if (selectedResult >= 0 && items[selectedResult]) items[selectedResult].click();
        }
    });
}

function bindKeyboard() {
    document.addEventListener('keydown', function (e) {
        var tag = document.activeElement && document.activeElement.tagName;
        if (e.key === '/' && tag !== 'INPUT' && tag !== 'TEXTAREA') {
            e.preventDefault();
            openSearch();
        } else if (e.key === 'Escape') {
            closeSearch();
            closeBookmarks();
            $('#sidebar').classList.remove('open');
        } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'b') {
            e.preventDefault();
            if ($('#bookmarksPanel').classList.contains('open')) closeBookmarks();
            else openBookmarks();
        }
    });
    $('#bookmarkToggle').addEventListener('click', function () {
        if ($('#bookmarksPanel').classList.contains('open')) closeBookmarks();
        else openBookmarks();
    });
    $('#closeBookmarks').addEventListener('click', closeBookmarks);
    $('#themeToggle').addEventListener('click', function () {
        var cur = document.documentElement.getAttribute('data-theme');
        var next = cur === 'dark' ? 'light' : 'dark';
        document.documentElement.setAttribute('data-theme', next);
        storage.set('dsa_theme', next);
    });
}

/* -------- module: core/09-langtabs.js -------- */

/* ============================================================
   DSA Knowledge Base - script.js (module: langtabs)
   Content Database + App Logic | Vanilla JS | No dependencies
   ============================================================ */

/* ---------- Language Tab Groups ----------
   All .code-explain blocks sharing the same data-group render as
   one tabbed widget (C · C++ · Java · Python · Dart). Tabs default
   to the user's preferred language (if present), else C++.

   Every code block also carries a .lang-switch <select>:
   - inside a group  -> switches the group's active tab
   - standalone      -> jumps to the same snippet under the same
                        heading on this page.

   The home page asks the user for their preferred language on first
   visit (persisted via safe storage) and offers a persistent control
   to change it. */

var groupWidgets = [];
var groupWidgetsActive = {};

/* ---------- Preferred language ---------- */

var PREF_KEY = 'dsa_lang';
var PREF_ASKED_KEY = 'dsa_lang_asked';

function getPrefLang() {
    var v = storage.get(PREF_KEY);
    return LANG_ORDER.indexOf(v) !== -1 ? v : null;
}

function setPrefLang(l) {
    if (LANG_ORDER.indexOf(l) !== -1) storage.set(PREF_KEY, l);
}

function applyPrefToGroups() {
    var pref = getPrefLang();
    if (!pref) return;
    $$('.code-explain[data-group]').forEach(function (el) {
        var g = el.getAttribute('data-group');
        if (!g) return;
        var present = $$('.code-explain[data-group="' + g + '"]').some(function (x) {
            return x.getAttribute('data-lang') === pref;
        });
        if (present) {
            groupWidgetsActive[g] = pref;
            activateGroup(g, pref);
        }
    });
}

/* ---------- Language tab groups ---------- */

function initLangTabs(root) {
    var scope = root || document;
    var groups = {};
    $$('.code-explain[data-group]', scope).forEach(function (el) {
        var g = el.getAttribute('data-group');
        if (!g) return;
        if (!groups[g]) groups[g] = [];
        groups[g].push(el);
    });

    Object.keys(groups).forEach(function (g) {
        var widgets = groups[g];
        if (widgets.length < 2) return;
        var langs = widgets.map(function (w) { return w.getAttribute('data-lang'); });
        var defaultLang = langs.indexOf('cpp') !== -1 ? 'cpp' : langs[0];
        var persisted = groupWidgetsActive[g];
        var pref = getPrefLang();
        var initial = persisted !== undefined && langs.indexOf(persisted) !== -1 ? persisted
            : pref && langs.indexOf(pref) !== -1 ? pref
            : defaultLang;

        var bar = document.createElement('div');
        bar.className = 'lang-tabs';
        langs.forEach(function (l) {
            var btn = document.createElement('button');
            btn.className = 'lang-tab';
            btn.setAttribute('data-group', g);
            btn.setAttribute('data-lang', l);
            btn.textContent = langName(l);
            btn.addEventListener('click', function () {
                activateGroup(g, l);
            });
            bar.appendChild(btn);
        });

        var first = widgets[0];
        first.parentNode.insertBefore(bar, first);
        activateGroup(g, initial);
    });
}

function activateGroup(g, lang) {
    groupWidgetsActive[g] = lang;
    $$('.code-explain[data-group="' + g + '"]').forEach(function (el) {
        var isActive = el.getAttribute('data-lang') === lang;
        el.style.display = isActive ? '' : 'none';
    });
    $$('.lang-tab[data-group="' + g + '"]').forEach(function (btn) {
        btn.classList.toggle('active', btn.getAttribute('data-lang') === lang);
    });
    $$('.code-explain[data-group="' + g + '"] .lang-switch').forEach(function (sel) {
        sel.value = lang;
    });
}

/* ---------- Per-block language switcher ---------- */

function flashBlock(el) {
    el.style.boxShadow = '0 0 0 3px var(--accent-primary)';
    setTimeout(function () { el.style.boxShadow = ''; }, 1600);
}

function blockContext(block) {
    var node = block.previousElementSibling;
    while (node) {
        if (node.tagName && /^H[1-4]$/.test(node.tagName)) return node.tagName + '|' + node.textContent.trim();
        node = node.previousElementSibling;
    }
    return '';
}

function findTwinBlock(article, block, targetLang) {
    var ctx = blockContext(block);
    var candidates = $$('.code-block[data-lang="' + targetLang + '"]', article);
    for (var i = 0; i < candidates.length; i++) {
        var c = candidates[i];
        if (c === block) continue;
        if (c.closest && c.closest('.code-explain')) continue;
        if (blockContext(c) === ctx) return c;
    }
    return null;
}

function switchBlockLanguage(block, targetLang) {
    var explain = block.closest && block.closest('.code-explain');
    var g = explain ? explain.getAttribute('data-group') : null;
    if (g) {
        if ($$('.code-explain[data-group="' + g + '"][data-lang="' + targetLang + '"]').length) {
            activateGroup(g, targetLang);
            return;
        }
        toast('No ' + langName(targetLang) + ' version in this group');
        block.querySelector('.lang-switch').value = explain.getAttribute('data-lang');
        return;
    }
    var sel = block.querySelector('.lang-switch');
    var target = findTwinBlock($('#article'), block, targetLang);
    if (target) {
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
        flashBlock(target);
        var tsel = target.querySelector('.lang-switch');
        if (tsel) tsel.value = target.getAttribute('data-lang');
    } else {
        toast('No ' + langName(targetLang) + ' version on this page');
    }
    if (sel) sel.value = block.getAttribute('data-lang');
}

function initBlockSwitchers(root) {
    var scope = root || document;
    $$('.lang-switch', scope).forEach(function (sel) {
        if (sel.__wired) return;
        sel.__wired = true;
        sel.addEventListener('change', function () {
            var block = sel.closest('.code-block');
            if (!block) return;
            switchBlockLanguage(block, sel.value);
        });
    });
}

/* ---------- Problem cards ("View code") ---------- */

function initProblemSolutionButtons(root) {
    var scope = root || document;
    $$('.problem-solution-btn', scope).forEach(function (btn) {
        if (btn.__wired) return;
        btn.__wired = true;
        btn.addEventListener('click', function () {
            var g = btn.getAttribute('data-group');
            var target = $('.code-explain[data-group="' + g + '"]');
            if (!target) return;
            var active = groupWidgetsActive[g];
            if (!active) {
                var tab = $('.lang-tab[data-group="' + g + '"]');
                active = tab ? tab.getAttribute('data-lang') : 'cpp';
            }
            activateGroup(g, active);
            target.scrollIntoView({ behavior: 'smooth', block: 'start' });
            flashBlock(target);
        });
    });
}

/* ---------- Preferred language ask (home page) ---------- */

function renderLangPrefBar() {
    var article = $('#article');
    if (!article || article.querySelector('.lang-pref-bar')) return;
    var cur = getPrefLang();
    var html = '<div class="lang-pref-bar">' +
        '<span class="lang-pref-label">Preferred language:</span>' +
        '<select id="langPrefSelect" class="lang-pref-select" aria-label="Preferred language">' +
        langSelectOptions(cur) +
        '</select>' +
        '<span class="lang-pref-hint">Code tabs default to this language.</span>' +
        '</div>';
    article.insertAdjacentHTML('afterbegin', html);
    var sel = $('#langPrefSelect');
    if (sel) {
        sel.addEventListener('change', function () {
            setPrefLang(this.value);
            applyPrefToGroups();
            toast('Preferred language: ' + langName(this.value));
        });
    }
}

function closeLangPrefModal() {
    var modal = $('#langPrefModal');
    if (modal) modal.classList.remove('open');
}

function chooseLangPref(l) {
    setPrefLang(l);
    storage.set(PREF_ASKED_KEY, '1');
    closeLangPrefModal();
    var homeSel = $('#langPrefSelect');
    if (homeSel) homeSel.value = l;
    applyPrefToGroups();
    toast('Preferred language: ' + langName(l));
}

function initLangPref() {
    safe(initLangPrefModal);
    renderLangPrefBar();
    if (getPrefLang() || storage.get(PREF_ASKED_KEY)) return;
    var modal = $('#langPrefModal');
    if (!modal) return;
    modal.classList.add('open');
}

var langPrefWired = false;

function initLangPrefModal() {
    if (langPrefWired) return;
    langPrefWired = true;
    var modal = $('#langPrefModal');
    if (!modal) return;
    $$('.lang-pref-option', modal).forEach(function (btn) {
        btn.addEventListener('click', function () {
            chooseLangPref(btn.getAttribute('data-lang'));
        });
    });
    var skip = $('#langPrefSkip');
    if (skip) {
        skip.addEventListener('click', function () {
            storage.set(PREF_ASKED_KEY, '1');
            closeLangPrefModal();
        });
    }
    $('#langPrefBackdrop').addEventListener('click', function () {
        storage.set(PREF_ASKED_KEY, '1');
        closeLangPrefModal();
    });
}

/* ---------- Entry point ---------- */

function initLangTabsAll() {
    initLangPrefModal();
    initLangTabs(document);
    initBlockSwitchers(document);
    initProblemSolutionButtons(document);
}

