            '',
            '## Reverse an Array',
            '',
            'Flip the array in place with two pointers — one from each end — swapping until they cross. O(n) time, O(1) space.',
            '',
            '~~~explain',
            'lang: c',
            'group: reverse',
            '#include <stdio.h>',
            'int main() {',
            '    int a[] = {1, 2, 3, 4, 5};',
            '    int n = 5;',
            '    printf("before: ");',
            '    for (int i = 0; i < n; i++) printf("%d ", a[i]);',
            '    printf("\\n");',
            '    for (int i = 0, j = n - 1; i < j; i++, j--) {',
            '        int t = a[i];',
            '        a[i] = a[j];',
            '        a[j] = t;',
            '    }',
            '    printf("after: ");',
            '    for (int i = 0; i < n; i++) printf("%d ", a[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## Includes the standard input/output header so `printf` is available. [stdio]({c:stdio})',
            '##2## Every C program starts executing in `main()`. [main]({c:main})',
            '##3## The array to reverse. [Arrays]({c:array})',
            '##4## The array length. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Prints the stage label. [printf]({c:printf})',
            '##6## Prints the original array. [for]({c:for})',
            '##8## Two pointers close in from both ends. [for]({c:for})',
            '##9## A temporary holds one value during the swap. [Variables](https://www.learn-c.org/en/Variables)',
            '##10## Copies the right-hand value into the left slot. [Arrays]({c:array})',
            '##11## Completes the swap. [Arrays]({c:array})',
            '##13## Prints the stage label. [printf]({c:printf})',
            '##14## Prints the reversed array. [for]({c:for})',
            '##16## Success exit. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: reverse',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int main() {',
            '    vector<int> a = {1, 2, 3, 4, 5};',
            '    cout << "before: ";',
            '    for (int x : a) cout << x << " ";',
            '    cout << "\\n";',
            '    reverse(a.begin(), a.end());',
            '    cout << "after: ";',
            '    for (int x : a) cout << x << " ";',
            '    cout << "\\n";',
            '    return 0;',
            '}',
            '---',
            '##1## Imports the whole C++ standard library. [bits/stdc++.h](https://www.geeksforgeeks.org/bitsstdc-h-c/)',
            '##2## Lets you write `cout` instead of `std::cout`. [namespace]({cpp:namespace})',
            '##3## Program entry point. [main]({cpp:main})',
            '##4## A `vector` holding the values to reverse. [vector]({cpp:vector})',
            '##5## Prints the stage label. [cout]({cpp:cout})',
            '##6## Prints the original array. [for](https://en.cppreference.com/w/cpp/language/range-for)',
            '##8## `std::reverse` flips the whole range in place. [reverse](https://en.cppreference.com/w/cpp/algorithm/reverse)',
            '##9## Prints the stage label. [cout]({cpp:cout})',
            '##10## Prints the reversed array. [for](https://en.cppreference.com/w/cpp/language/range-for)',
            '##12## Success exit. [return](https://en.cppreference.com/w/cpp/language/return)',
            '~~~',
            '',
            '~~~explain',
            'lang: java',
            'group: reverse',
            'import java.util.*;',
            'public class Main {',
            '    public static void main(String[] args) {',
            '        int[] a = {1, 2, 3, 4, 5};',
            '        System.out.println("before:");',
            '        for (int x : a) System.out.print(x + " ");',
            '        System.out.println();',
            '        int i = 0, j = a.length - 1;',
            '        while (i < j) {',
            '            int t = a[i];',
            '            a[i] = a[j];',
            '            a[j] = t;',
            '            i++;',
            '            j--;',
            '        }',
            '        System.out.println("after:");',
            '        for (int x : a) System.out.print(x + " ");',
            '        System.out.println();',
            '    }',
            '}',
            '---',
            '##1## Imports the `java.util` package. [import]({java:import})',
            '##2## In Java every function lives inside a class. [class]({java:class})',
            '##3## `main` is where execution starts. [main]({java:main})',
            '##4## The array to reverse. [Arrays](https://www.w3schools.com/java/java_arrays.asp)',
            '##5## Prints the stage label. [println]({java:println})',
            '##6## Prints the original array. [for]({java:for})',
            '##8## Two pointers close in from both ends. [Variables](https://www.w3schools.com/java/java_variables.asp)',
            '##9## Swap until the pointers cross. [while](https://www.w3schools.com/java/java_while_loop.asp)',
            '##10## A temporary holds one value during the swap. [Variables](https://www.w3schools.com/java/java_variables.asp)',
            '##11## Copies the right-hand value into the left slot. [Arrays](https://www.w3schools.com/java/java_arrays.asp)',
            '##12## Completes the swap. [Arrays](https://www.w3schools.com/java/java_arrays.asp)',
