            '',
            '~~~explain',
            'lang: dart',
            'group: windowmax',
            'void main() {',
            '  var a = [1, 4, 2, 10, 23, 3, 1, 0, 20];',
            '  var k = 4;',
            '  var sum = a.sublist(0, k).fold(0, (p, v) => p + v);',
            '  var best = sum;',
