            '## Merge Intervals',
            '',
            'Sort by start, then merge any interval that touches the running one: if it starts at or before the running end, extend the end; otherwise start a new interval.',
            '',
            '~~~explain',
            'lang: c',
            'group: intervalmerge',
            '#include <stdio.h>',
            'int main() {',
            '    int a[4][2] = {{1, 3}, {2, 6}, {8, 10}, {15, 18}};',
            '    int res[4][2];',
            '    int k = 0;',
            '    for (int i = 0; i < 4; i++) {',
            '        if (k == 0 || a[i][0] > res[k - 1][1]) {',
            '            res[k][0] = a[i][0];',
            '            res[k][1] = a[i][1];',
            '            k++;',
            '        } else if (a[i][1] > res[k - 1][1]) {',
            '            res[k - 1][1] = a[i][1];',
            '        }',
            '    }',
            '    for (int i = 0; i < k; i++) printf("[%d,%d] ", res[i][0], res[i][1]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
