            '~~~problem',
            'title: Move Zeroes',
            'difficulty: easy',
            'source: LeetCode 283 · Meta, Apple',
            'tags: array, two-pointers, in-place',
            'statement: Move all 0s to the end while keeping the relative order of non-zero elements, in-place.',
            'approach: Slow pointer `w` tracks the write position. Scan; when `arr[r] != 0`, write it at `w` and increment. Zero-fill the tail. This is the same-direction two-pointer pattern.',
            'time: O(n)',
            'space: O(1)',
            'solution: movezeroes',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: movezeroes',
            '#include <stdio.h>',
            'int main() {',
            '    int a[] = {0, 1, 0, 3, 12};',
            '    int n = 5;',
            '    int w = 0;',
            '    for (int r = 0; r < n; r++) {',
            '        if (a[r] != 0) {',
            '            a[w] = a[r];',
            '            w++;',
            '        }',
            '    }',
            '    for (int i = w; i < n; i++) a[i] = 0;',
            '    for (int i = 0; i < n; i++) printf("%d ", a[i]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## Entry point. [main]({c:main})',
            '##3## Input array with zeros to move. [Arrays]({c:array})',
            '##4## Array length. [Variables](https://www.learn-c.org/en/Variables)',
            '##5## Write pointer starts at index 0. [Variables](https://www.learn-c.org/en/Variables)',
            '##6## Read pointer scans every element. [For loops]({c:for})',
            '##7## Only copy non-zero values. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##8## Place the non-zero at the write position. [Arrays]({c:array})',
            '##9## Advance the write pointer. [Variables](https://www.learn-c.org/en/Variables)',
            '##12## Fill remaining slots with zeros. [For loops]({c:for})',
            '##13## Print the result. [For loops]({c:for})',
            '##15## Exit successfully. [return]({c:return})',
            '~~~',
            '',
            '~~~explain',
            'lang: cpp',
            'group: movezeroes',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'int main() {',
            '    vector<int> a = {0, 1, 0, 3, 12};',
            '    int w = 0;',
            '    for (int r = 0; r < a.size(); r++) {',
            '        if (a[r] != 0) a[w++] = a[r];',
            '    }',
            '    fill(a.begin() + w, a.end(), 0);',
            '    for (int x : a) cout << x << " ";',
            '    cout << "\\n";',
            '    return 0;',
            '}',
