            'lang: java',
            'group: movezeroes',
            'import java.util.*;',
            'public class Main {',
            '    public static void main(String[] args) {',
            '        int[] a = {0, 1, 0, 3, 12};',
            '        int w = 0;',
            '        for (int r = 0; r < a.length; r++) {',
            '            if (a[r] != 0) a[w++] = a[r];',
            '        }',
