            'import java.util.*;',
            'public class Main {',
            '    static int subarraySum(int[] nums, int k) {',
            '        Map<Integer, Integer> prefix = new HashMap<>();',
            '        int pref = 0, count = 0;',
            '        prefix.put(0, 1);',
            '        for (int x : nums) {',
            '            pref += x;',
            '            count += prefix.getOrDefault(pref - k, 0);',
            '            prefix.merge(pref, 1, Integer::sum);',
            '        }',
            '        return count;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] nums = {1, 1, 1};',
            '        System.out.println(subarraySum(nums, 2));',
            '    }',
