            '~~~problem',
            'title: Longest Substring Without Repeating Characters',
            'difficulty: medium',
            'source: LeetCode 3 · Amazon, Google',
            'tags: array, sliding-window, hashset',
            'statement: Length of the longest substring with all distinct characters.',
            'approach: Variable window. `right` grows; while the window contains a duplicate, shrink from `left`. Track the max window size. Character set gives O(1) membership.',
            'time: O(n)',
            'space: O(k), k = alphabet size',
            'solution: longestsubstr',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: longestsubstr',
            '#include <stdio.h>',
            '#include <string.h>',
            'int lengthOfLongestSubstring(char* s) {',
            '    int seen[128] = {0};',
            '    int left = 0, maxLen = 0;',
            '    for (int right = 0; s[right]; right++) {',
            '        while (seen[s[right]]) {',
            '            seen[s[left]] = 0;',
            '            left++;',
            '        }',
            '        seen[s[right]] = 1;',
            '        int len = right - left + 1;',
            '        if (len > maxLen) maxLen = len;',
            '    }',
            '    return maxLen;',
            '}',
            'int main() {',
            '    char s[] = "abcabcbb";',
            '    printf("%d\\n", lengthOfLongestSubstring(s));',
            '    return 0;',
            '}',
