            'public class Main {',
            '    static int lengthOfLongestSubstring(String s) {',
            '        int[] seen = new int[128];',
            '        int left = 0, maxLen = 0;',
            '        for (int right = 0; right < s.length(); right++) {',
            '            while (seen[s.charAt(right)]++) {',
            '                seen[s.charAt(left)] = 0;',
            '                left++;',
            '            }',
            '            maxLen = Math.max(maxLen, right - left + 1);',
            '        }',
            '        return maxLen;',
            '    }',
