            '~~~problem',
            'title: Container With Most Water',
            'difficulty: medium',
            'source: LeetCode 11 · Amazon, Meta',
            'tags: array, two-pointers, greedy',
            'statement: Height array; choose two lines that hold the most water.',
            'approach: `l=0, r=n-1`. Area = `min(h[l], h[r]) * (r - l)`. Move the shorter line inward — the taller one might still pair with a taller line. Greedy is provably optimal.',
            'time: O(n)',
            'space: O(1)',
            'solution: containerwater',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: containerwater',
            '#include <stdio.h>',
            'int maxArea(int* h, int n) {',
            '    int l = 0, r = n - 1, best = 0;',
            '    while (l < r) {',
            '        int area = (h[l] < h[r] ? h[l] : h[r]) * (r - l);',
            '        if (area > best) best = area;',
            '        if (h[l] < h[r]) l++;',
            '        else r--;',
            '    }',
            '    return best;',
            '}',
            'int main() {',
            '    int h[] = {1, 8, 6, 2, 5, 4, 8, 3, 7};',
            '    int n = 9;',
            '    printf("%d\\n", maxArea(h, n));',
            '    return 0;',
            '}',
            '---',
