            'lang: c',
            'group: maxprodsubarray',
            '#include <stdio.h>',
            'int maxProduct(int* nums, int n) {',
            '    int maxEnd = nums[0], minEnd = nums[0], result = nums[0];',
            '    for (int i = 1; i < n; i++) {',
            '        int temp = maxEnd;',
            '        if (nums[i] < 0) { maxEnd = minEnd; minEnd = temp; }',
            '        maxEnd = nums[i] > maxEnd * nums[i] ? nums[i] : maxEnd * nums[i];',
            '        minEnd = nums[i] < minEnd * nums[i] ? nums[i] : minEnd * nums[i];',
            '        if (maxEnd > result) result = maxEnd;',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    int nums[] = {2, 3, -2, 4};',
            '    int n = 4;',
            '    printf("%d\\n", maxProduct(nums, n));',
            '    return 0;',
            '}',
