            'title: Merge Intervals',
            'difficulty: medium',
            'source: LeetCode 56 · Amazon, Facebook',
            'tags: array, sorting, intervals',
            'statement: Merge all overlapping intervals.',
            'approach: Sort by start. Walk; overlap if `it[0] <= last.end`, then extend `last.end`. Otherwise push a new interval.',
            'time: O(n log n)',
            'space: O(n)',
            'solution: mergeintervals',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: mergeintervals',
            '#include <stdio.h>',
            '#include <stdlib.h>',
            'int cmp(const void* a, const void* b) {',
            '    return (*(int**)a)[0] - (*(int**)b)[0];',
            '}',
            'int main() {',
            '    int intervals[][2] = {{1,3},{2,6},{8,10},{15,18}};',
            '    int n = 4;',
            '    qsort(intervals, n, sizeof(int[2]), cmp);',
            '    int result[n][2], r = 0;',
            '    result[0][0] = intervals[0][0];',
            '    result[0][1] = intervals[0][1];',
            '    for (int i = 1; i < n; i++) {',
            '        if (intervals[i][0] <= result[r][1]) {',
            '            if (intervals[i][1] > result[r][1]) result[r][1] = intervals[i][1];',
            '        } else {',
            '            r++;',
            '            result[r][0] = intervals[i][0];',
            '            result[r][1] = intervals[i][1];',
            '        }',
            '    }',
            '    for (int i = 0; i <= r; i++) printf("[%d,%d] ", result[i][0], result[i][1]);',
            '    printf("\\n");',
            '    return 0;',
            '}',
            '---',
