            '~~~problem',
            'title: Find All Anagrams in a String',
            'difficulty: medium',
            'source: LeetCode 438 · Amazon, Microsoft',
            'tags: array, sliding-window, frequency',
            'statement: All start indices of `p`\'s anagrams in `s`.',
            'approach: Fixed window of length `len(p)`; maintain a 26-length frequency diff. When the diff is all zeros, the window is an anagram.',
            'time: O(n)',
            'space: O(1)',
            'solution: findanagrams',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: findanagrams',
            '#include <stdio.h>',
            '#include <string.h>',
            'int* findAnagrams(char* s, char* p, int* returnSize) {',
            '    int slen = strlen(s), plen = strlen(p);',
            '    int* result = (int*)malloc(slen * sizeof(int));',
            '    *returnSize = 0;',
            '    if (slen < plen) return result;',
            '    int freq[26] = {0};',
            '    for (int i = 0; i < plen; i++) {',
            '        freq[p[i] - \'a\']++;',
            '        freq[s[i] - \'a\']--;',
            '    }',
            '    int diff = 0;',
            '    for (int i = 0; i < 26; i++) if (freq[i] != 0) diff++;',
            '    if (diff == 0) result[(*returnSize)++] = 0;',
            '    for (int i = plen; i < slen; i++) {',
            '        if (freq[s[i] - \'a\'] == 0) diff++;',
            '        freq[s[i] - \'a\']--;',
            '        if (freq[s[i] - \'a\'] == 0) diff--;',
            '        if (freq[s[i - plen] - \'a\'] == 0) diff++;',
            '        freq[s[i - plen] - \'a\']++;',
            '        if (freq[s[i - plen] - \'a\'] == 0) diff--;',
            '        if (diff == 0) result[(*returnSize)++] = i - plen + 1;',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    char s[] = "cbaebabacd", p[] = "abc";',
            '    int returnSize;',
            '    int* result = findAnagrams(s, p, &returnSize);',
            '    for (int i = 0; i < returnSize; i++) printf("%d ", result[i]);',
            '    printf("\\n");',
            '    free(result);',
            '    return 0;',
            '}',
            '---',
            '##1## Standard I/O header. [stdio]({c:stdio})',
            '##2## String functions. [string](https://en.cppreference.com/w/c/header/string)',
            '##3## Function returns array of start indices. [Functions](https://www.learn-c.org/en/Functions)',
            '##4## Get string lengths. [strlen](https://en.cppreference.com/w/c/string/byte/strlen)',
            '##5## Allocate result array. [malloc]({c:malloc})',
            '##7## Pattern longer than string: no matches. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##8## Frequency difference array. [Arrays]({c:array})',
            '##9## Build frequency diff for first window. [For loops]({c:for})',
            '##13## Count non-zero frequency differences. [For loops]({c:for})',
            '##15## First window is an anagram. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##16## Slide the window. [For loops]({c:for})',
            '##22## Check if current window is an anagram. [If statements](https://www.learn-c.org/en/If_Statements)',
            '##25## Return result array. [return]({c:return})',
            '##26## Entry point. [main]({c:main})',
            '##28## Print indices. [For loops]({c:for})',
            '##30## Free allocated memory. [free]({c:free})',
            '##31## Exit successfully. [return]({c:return})',
            '~~~',
