            '~~~explain',
            'lang: cpp',
            'group: findanagrams',
            '#include <bits/stdc++.h>',
            'using namespace std;',
            'vector<int> findAnagrams(string s, string p) {',
            '    vector<int> result;',
            '    if (s.size() < p.size()) return result;',
            '    vector<int> freq(26, 0);',
            '    for (int i = 0; i < p.size(); i++) {',
            '        freq[p[i] - \'a\']++;',
