            'int trap(int* h, int n) {',
            '    int l = 0, r = n - 1, lMax = 0, rMax = 0, water = 0;',
            '    while (l < r) {',
            '        if (h[l] < h[r]) {',
            '            if (h[l] >= lMax) lMax = h[l];',
            '            else water += lMax - h[l];',
            '            l++;',
            '        } else {',
            '            if (h[r] >= rMax) rMax = h[r];',
            '            else water += rMax - h[r];',
            '            r--;',
            '        }',
            '    }',
            '    return water;',
            '}',
