            '~~~problem',
            'title: Sliding Window Maximum',
            'difficulty: hard',
            'source: LeetCode 239 · Amazon, Facebook',
            'tags: array, deque, sliding-window',
            'statement: Maximum of every window of size `k`.',
            'approach: Monotonic deque holding candidate indices, decreasing by value. New element evicts smaller values from the back; expired indices pop from the front. The front is always the window max.',
            'time: O(n)',
            'space: O(k)',
            'solution: slidingwindowmax',
            '~~~',
            '',
            '~~~explain',
            'lang: c',
            'group: slidingwindowmax',
            '#include <stdio.h>',
            'int* maxSlidingWindow(int* nums, int n, int k, int* returnSize) {',
            '    int* result = (int*)malloc((n - k + 1) * sizeof(int));',
            '    *returnSize = n - k + 1;',
            '    int deque[n], front = 0, back = 0;',
            '    for (int i = 0; i < n; i++) {',
            '        while (front < back && nums[deque[back - 1]] <= nums[i]) back--;',
            '        deque[back++] = i;',
            '        if (deque[front] <= i - k) front++;',
            '        if (i >= k - 1) result[i - k + 1] = nums[deque[front]];',
            '    }',
            '    return result;',
            '}',
            'int main() {',
            '    int nums[] = {1, 3, -1, -3, 5, 3, 6, 7};',
            '    int n = 8, k = 3, returnSize;',
            '    int* result = maxSlidingWindow(nums, n, k, &returnSize);',
            '    for (int i = 0; i < returnSize; i++) printf("%d ", result[i]);',
            '    printf("\\n");',
            '    free(result);',
            '    return 0;',
            '}',
            '---',
