            '~~~explain',
            'lang: java',
            'group: slidingwindowmax',
            'import java.util.*;',
            'public class Main {',
            '    static int[] maxSlidingWindow(int[] nums, int k) {',
            '        int n = nums.length;',
            '        int[] result = new int[n - k + 1];',
            '        Deque<Integer> dq = new ArrayDeque<>();',
            '        for (int i = 0; i < n; i++) {',
            '            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[i]) dq.pollLast();',
            '            dq.offerLast(i);',
            '            if (dq.peekFirst() <= i - k) dq.pollFirst();',
            '            if (i >= k - 1) result[i - k + 1] = nums[dq.peekFirst()];',
            '        }',
            '        return result;',
            '    }',
            '    public static void main(String[] args) {',
            '        int[] nums = {1, 3, -1, -3, 5, 3, 6, 7};',
            '        System.out.println(Arrays.toString(maxSlidingWindow(nums, 3)));',
            '    }',
            '}',
            '---',
            '##1## Imports utility classes. [import]({java:import})',
            '##2## All methods live in a class. [class]({java:class})',
            '##3## Static method returns max per window. [static](https://docs.oracle.com/javase/tutorial/java/javaOO/classvariables.html)',
            '##4## Array length. [length](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/arrays.html)',
            '##5## Result array. [Arrays](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/arrays.html)',
            '##6## Monotonic deque. [ArrayDeque](https://docs.oracle.com/javase/8/docs/api/java/util/ArrayDeque.html)',
            '##7## Process each element. [for]({java:for})',
            '##8## Evict smaller from back. [while](https://docs.oracle.com/javase/tutorial/java/nutsandbolts/while.html)',
            '##9## Add current index. [offerLast](https://docs.oracle.com/javase/8/docs/api/java/util/Deque.html)',
            '##10## Remove expired index. [pollFirst](https://docs.oracle.com/javase/8/docs/api/java/util/Deque.html)',
            '##11## Record max. [peekFirst](https://docs.oracle.com/javase/8/docs/api/java/util/Deque.html)',
            '##13## Return result. [return]({java:return})',
            '##14## Entry point. [main]({java:main})',
            '##15## Print result. [Arrays.toString](https://docs.oracle.com/javase/8/docs/api/java/util/Arrays.html)',
            '~~~',
            '',
            '~~~explain',
            'lang: python',
            'group: slidingwindowmax',
            'from collections import deque',
            'def main():',
            '    nums = [1, 3, -1, -3, 5, 3, 6, 7]',
            '    k = 3',
            '    dq = deque()',
            '    result = []',
            '    for i in range(len(nums)):',
            '        while dq and nums[dq[-1]] <= nums[i]:',
            '            dq.pop()',
            '        dq.append(i)',
            '        if dq[0] <= i - k:',
            '            dq.popleft()',
            '        if i >= k - 1:',
            '            result.append(nums[dq[0]])',
            '    print(result)',
            '',
            'main()',
            '---',
            '##1## Import deque from collections. [import](https://docs.python.org/3/reference/simple_stmts.html#import)',
            '##2## Function definition. [def]({python:def})',
            '##3## Input list. [list]({python:list})',
            '##4## Window size. [Variables](https://www.w3schools.com/python/python_variables.asp)',
            '##5## Monotonic deque. [deque](https://docs.python.org/3/library/collections.html#deque)',
            '##6## Result list. [list]({python:list})',
            '##7## Process each element. [range]({python:range})',
            '##8## Evict smaller from back. [while](https://docs.python.org/3/reference/compound_stmts.html#while)',
            '##10## Add current index. [deque](https://docs.python.org/3/library/collections.html#deque)',
            '##11## Remove expired index. [if]({python:if})',
            '##13## Record max. [list]({python:list})',
            '##15## Print result. [print]({python:print})',
            '##17## Run the function. [main]({python:main})',
            '~~~',
            '',
            '~~~explain',
            'lang: dart',
            'group: slidingwindowmax',
            'void main() {',
            '  var nums = [1, 3, -1, -3, 5, 3, 6, 7];',
            '  var k = 3;',
            '  var dq = <int>[];',
            '  var result = <int>[];',
            '  for (var i = 0; i < nums.length; i++) {',
            '    while (dq.isNotEmpty && nums[dq.last] <= nums[i]) dq.removeLast();',
            '    dq.add(i);',
            '    if (dq.first <= i - k) dq.removeAt(0);',
            '    if (i >= k - 1) result.add(nums[dq.first]);',
            '  }',
            '  print(result);',
            '}',
            '---',
